using System.Text;

namespace NEXUS.Contracts.Configuration;

/// <summary>
///     Renders and parses the auto-generated, git-ignored repo-root <c>.env</c> file that mirrors the user-secrets
///     vault (docker compose, shell scripts and the CLI consume it). Quoting follows docker compose v2 rules:
///     single-quoted values are literal; values containing a single quote or a newline are double-quoted with
///     <c>\</c>, <c>"</c> and newlines escaped and <c>$</c> doubled to suppress interpolation.
/// </summary>
public static class DotEnvFile
{
    public const string HeaderMarker = "# AUTO-GENERATED BY NEXUS CONTROL PANEL";

    public static string Render(IEnumerable<KeyValuePair<string, string>> entries, string vaultPath)
    {
        StringBuilder builder = new();
        builder.AppendLine(HeaderMarker + " - DO NOT EDIT BY HAND");
        builder.AppendLine("# Source of truth: dotnet user-secrets vault (" + Path.GetFileName(Path.GetDirectoryName(vaultPath) ?? string.Empty) + ")");
        builder.AppendLine("# Edit values in: NEXUS Control Panel -> Secrets & Configs, then Save. This file is rewritten on every save.");
        builder.AppendLine("# This file contains secrets and is git-ignored. Never commit it.");
        builder.AppendLine();

        foreach (KeyValuePair<string, string> entry in entries)
            builder.Append(entry.Key).Append('=').AppendLine(Quote(entry.Value));

        return builder.ToString();
    }

    public static string Quote(string value)
    {
        if (!value.Contains('\'') && !value.Contains('\n') && !value.Contains('\r'))
            return "'" + value + "'";

        StringBuilder escaped = new(value.Length + 8);
        escaped.Append('"');
        foreach (char c in value)
            switch (c)
            {
                case '\\': escaped.Append("\\\\"); break;
                case '"': escaped.Append("\\\""); break;
                case '$': escaped.Append("$$"); break;
                case '\n': escaped.Append("\\n"); break;
                case '\r': escaped.Append("\\r"); break;
                default: escaped.Append(c); break;
            }

        escaped.Append('"');
        return escaped.ToString();
    }

    public static Dictionary<string, string> Parse(string content)
    {
        Dictionary<string, string> result = new(StringComparer.Ordinal);

        foreach (string rawLine in content.Split('\n'))
        {
            string line = rawLine.TrimEnd('\r').Trim();
            if (line.Length == 0 || line.StartsWith('#')) continue;

            int equals = line.IndexOf('=');
            if (equals <= 0) continue;

            string name = line[..equals].Trim();
            if (name.StartsWith("export ", StringComparison.Ordinal)) name = name[7..].Trim();
            string raw = line[(equals + 1)..];

            result[name] = Unquote(raw);
        }

        return result;
    }

    private static string Unquote(string raw)
    {
        if (raw.Length >= 2 && raw[0] == '\'' && raw[^1] == '\'') return raw[1..^1];

        if (raw.Length >= 2 && raw[0] == '"' && raw[^1] == '"')
        {
            string inner = raw[1..^1];
            StringBuilder builder = new(inner.Length);
            for (int i = 0; i < inner.Length; i++)
            {
                char c = inner[i];
                if (c == '\\' && i + 1 < inner.Length)
                {
                    char next = inner[++i];
                    builder.Append(next switch { 'n' => '\n', 'r' => '\r', _ => next });
                }
                else if (c == '$' && i + 1 < inner.Length && inner[i + 1] == '$')
                {
                    builder.Append('$');
                    i++;
                }
                else
                {
                    builder.Append(c);
                }
            }

            return builder.ToString();
        }

        int comment = raw.IndexOf(" #", StringComparison.Ordinal);
        return (comment >= 0 ? raw[..comment] : raw).Trim();
    }
}
